.greeting-container {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 4rem 2rem;
    max-width: 1200px;
    margin: 0 auto;
}

.greeting-text-container {
    flex: 1;
    padding-right: 2rem;
}

.greeting-image-container {
    flex-shrink: 0;
}

.greeting-image {
    width: 350px;
    height: 350px;
    border-radius: 50%;
    object-fit: cover;
    border: 3px solid rgba(0, 122, 255, 0.6);
    box-shadow: 0 0 20px rgba(0, 122, 255, 0.5), 0 0 30px rgba(0, 122, 255, 0.3);
    animation: float 3s ease-in-out infinite;
}

@media (max-width: 768px) {
    .greeting-container {
        flex-direction: column-reverse;
        text-align: center;
    }

    .greeting-text-container {
        padding-right: 0;
        margin-top: 2rem;
    }
}
